import type { FormModel } from '@reformer/core';
import type { RenderSchemaFn } from '@reformer/renderer-react';
import { Box, Section, InputField } from '@reformer/ui-kit';

const buildSchema = (model: FormModel<MyForm>): RenderSchemaFn<MyForm> => {
  return () => ({
    component: Box,
    componentProps: { className: 'grid grid-cols-2 gap-4' },
    children: [
      {
        component: Section,
        componentProps: { title: 'Личные данные', className: 'space-y-4' },
        children: [
          { value: model.$.firstName, component: InputField, componentProps: { label: 'Имя' } },
          { value: model.$.lastName, component: InputField, componentProps: { label: 'Фамилия' } },
        ],
      },
    ],
  });
};

import { hideWhen, type RenderBehaviorFn } from '@reformer/renderer-react';

// form захвачен в замыкание фабрики поведения.
const behavior: RenderBehaviorFn<CreditForm> = (schema) => {
  hideWhen(schema.node('mortgage-section'), () => form.loanType.value.value !== 'mortgage');
};

import { renderEffect } from '@reformer/renderer-react';

const wizardRef = schema.node('wizard').getRef<FormWizardHandle<CreditForm>>();
renderEffect(schema, () => {
  if (form.loanType.value.value === 'mortgage') {
    wizardRef.current?.goToStep(1);
  }
});

import { onComponentEvent } from '@reformer/renderer-react';

onComponentEvent(schema.node('wizard'), 'onSubmit', async () => {
  // `FormWizardProps.onSubmit` у ui-kit — это `() => void | Promise<void>`: аргументов нет,
  // снимок берётся из модели. Типизировать как `(values: CreditForm) => …` — TS2322.
  // Валидировать здесь руками не надо: кнопка отправки гейтит вызов через `config.validateAll`
  // и при провале сюда не доходит (reformer://docs/cdk/multi-step-submit).
  await submitCreditApplication(model.get());
});

import { onMount, onUnmount } from '@reformer/renderer-react';

const boundary = schema.node('data-boundary');
onMount(boundary, () => {
  void loadApplication(); // напр. загрузить данные и boundary.patchProps({ status: 'ready' })
  return () => console.log('cleanup');
});
onUnmount(schema.node('wizard'), () => console.log('wizard unmounted'));

